        const ex = ep[at].pos.x - bp.points[at].pos.x, ey = ep[at].pos.y - bp.points[at].pos.y;
        const rx = ep[at].pos.x - px, ry = ep[at].pos.y - py;
        const rg = Math.max(1, Math.hypot(rx, ry));
