    const tx = -uy, ty = ux;
    const sg = (tx * (vx - tgt.vel.x) + ty * (vy - tgt.vel.y)) >= 0 ? 1 : -1;
    const orb = cl((1100 - td) / 1100, 0, 1) * cl((td - 250) / 250, 0, 1) * 80;
